/* Pixel palette: #2d1b69 (bg), #f5e6d3 (card), #ff6b6b (accent), #4ecdc4 (secondary), #1a1a2e (text) */
* { box-sizing: border-box; margin: 0; padding: 0; }
body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #2d1b69;
  font-family: 'Courier New', monospace;
  font-size: 16px;
  color: #1a1a2e;
  padding: 16px;
}
.card {
  background: #f5e6d3;
  border: 4px solid #1a1a2e;
  box-shadow: 8px 8px 0 #1a1a2e;
  padding: 24px;
  width: 100%;
  max-width: 480px;
  image-rendering: pixelated;
}
h1 {
  font-size: 1.5rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-bottom: 16px;
  border-bottom: 4px solid #1a1a2e;
  padding-bottom: 8px;
}
.input-row {
  display: flex;
  gap: 8px;
  margin-bottom: 16px;
}
input[type="text"] {
  flex: 1;
  padding: 10px;
  border: 3px solid #1a1a2e;
  background: #fff;
  font-family: inherit;
  font-size: 1rem;
  outline: none;
}
input[type="text"]:focus {
  border-color: #ff6b6b;
  box-shadow: 0 0 0 2px #ff6b6b;
}
button {
  padding: 10px 16px;
  border: 3px solid #1a1a2e;
  background: #ff6b6b;
  color: #1a1a2e;
  font-family: inherit;
  font-size: 1rem;
  font-weight: bold;
  cursor: pointer;
  text-transform: uppercase;
  transition: transform 0.05s, box-shadow 0.05s;
  box-shadow: 3px 3px 0 #1a1a2e;
}
button:hover { background: #ff8e8e; }
button:active { transform: translate(2px, 2px); box-shadow: 1px 1px 0 #1a1a2e; }
button:focus-visible { outline: 3px solid #4ecdc4; outline-offset: 2px; }
.counts {
  display: flex;
  justify-content: space-between;
  margin-bottom: 16px;
  font-weight: bold;
  padding: 8px;
  background: #4ecdc4;
  border: 3px solid #1a1a2e;
}
.list { list-style: none; }
.list li {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px;
  border: 3px solid #1a1a2e;
  margin-bottom: 8px;
  background: #fff;
}
.list li input[type="checkbox"] {
  width: 20px;
  height: 20px;
  accent-color: #ff6b6b;
  cursor: pointer;
  flex-shrink: 0;
}
.list li span {
  flex: 1;
  word-break: break-word;
}
.list li span.done {
  text-decoration: line-through;
  opacity: 0.6;
}
.list li button {
  padding: 4px 8px;
  font-size: 0.85rem;
  background: #4ecdc4;
  box-shadow: 2px 2px 0 #1a1a2e;
}
.list li button:hover { background: #6ee7de; }
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}
@media (max-width: 400px) {
  .card { padding: 16px; }
  h1 { font-size: 1.2rem; }
  .input-row { flex-direction: column; }
  button { width: 100%; }
}

(function() {
  'use strict';

  var tasks = [];
  var nextId = 1;

  var input = document.getElementById('todo-input');
  var addBtn = document.getElementById('todo-add');
  var totalEl = document.getElementById('todo-total');
  var remainingEl = document.getElementById('remaining');
  var listEl = document.getElementById('todo-list');

  function updateCounts() {
    totalEl.textContent = tasks.length;
    var incomplete = tasks.filter(function(t) { return !t.done; }).length;
    remainingEl.textContent = incomplete;
  }

  function createTaskElement(task) {
    var li = document.createElement('li');

    var checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.id = 'todo-check-' + task.id;
    checkbox.checked = task.done;
    checkbox.setAttribute('aria-label', 'Mark task as done: ' + task.text);

    var span = document.createElement('span');
    span.id = 'todo-text-' + task.id;
    span.textContent = task.text;
    if (task.done) span.classList.add('done');

    var delBtn = document.createElement('button');
    delBtn.type = 'button';
    delBtn.id = 'todo-delete-' + task.id;
    delBtn.textContent = 'Delete';
    delBtn.setAttribute('aria-label', 'Delete task: ' + task.text);

    checkbox.addEventListener('change', function() {
      task.done = checkbox.checked;
      span.classList.toggle('done', task.done);
      updateCounts();
    });

    delBtn.addEventListener('click', function() {
      var idx = tasks.indexOf(task);
      if (idx !== -1) tasks.splice(idx, 1);
      li.remove();
      updateCounts();
    });

    li.appendChild(checkbox);
    li.appendChild(span);
    li.appendChild(delBtn);
    return li;
  }

  function addTask() {
    var text = input.value.trim();
    if (!text) return;

    var task = { id: nextId++, text: text, done: false };
    tasks.push(task);
    listEl.appendChild(createTaskElement(task));
    input.value = '';
    input.focus();
    updateCounts();
  }

  addBtn.addEventListener('click', addTask);
  input.addEventListener('keydown', function(e) {
    if (e.key === 'Enter') addTask();
  });

  updateCounts();
})();
